const T = 1;

const RANGES = {
    s1: [0, 100],
    s2: [0, 14],
    s3: [2, 400]
};

const text = String(msg.payload).replace(/^\uFEFF/, '');
const sql = [];

function sqlString(value) {
    return "'" + String(value).replace(/'/g, "''") + "'";
}

text.split(/\r?\n/).forEach(raw => {
    const line = raw.trim();
    if (!line) return;

    const parts = line.split(/\s+/);
    const kind = parts[0];

    const f = {};

    parts.slice(1).forEach(p => {
        const i = p.indexOf('=');
        if (i > 0) {
            f[p.substring(0, i)] = p.substring(i + 1);
        }
    });

    const n = parseInt(f.n);

    if (isNaN(n) || n < 0) return;

    const t = n * T;

    if (kind === 'DATA') {

        ['s1', 's2', 's3'].forEach(s => {

            const v = Number(f[s]);

            // Проверка наличия и корректности значения
            if (
                f[s] === undefined ||
                f[s].trim() === '' ||
                !Number.isFinite(v) ||
                v < RANGES[s][0] ||
                v > RANGES[s][1]
            ) {

                // Запись неисправности FAULT
                const message = 'датчик ' + s + ' вне диапазона';

                sql.push(
                    `INSERT INTO events(n,t_s,type,message)
                    VALUES(${n},${t},'FAULT',${sqlString(message)});`
                );

            } else {

                // Запись показаний датчика
                sql.push(
                    `INSERT INTO readings(n,t_s,sensor,value)
                    VALUES(${n},${t},${sqlString(s)},${v});`
                );

            }
        });

    } else if (kind === 'EVENT') {

        // Запись события THRESHOLD или NORMAL
        if (f.type === 'THRESHOLD' || f.type === 'NORMAL') {

            sql.push(
                `INSERT INTO events(n,t_s,type,message)
                VALUES(${n},${t},${sqlString(f.type)},'');`
            );

        }
    }
});

// Формирование SQL-файла
const head =
    'BEGIN;\n' +
    'DELETE FROM readings;\n' +
    'DELETE FROM events;\n' ;

const result = head + sql.join('\n') + '\nCOMMIT;\n';

// Второй выход подключается к узлу file
return [null, { payload: result }];
